 if(action==='mail-status'){const r=LOCAL_DEMO?{enabled:true,mode:'demo',pending:0,failed:0,sent:0}:await api('/admin/mail','GET',undefined,true);modal('<h2>Почтовые уведомления</h2><p class="muted">'+(r.mode==='demo'?'Демонстрация: письма не отправляются. Подтверждение кабинета и восстановление можно проверить по тестовой ссылке на сайте.':r.enabled?'Отправка настроена.':'Отправка не настроена. Укажите SMTP и адрес отправителя в конфигурации сервера.')+'</p><p>В очереди: '+r.pending+' · Ошибки: '+r.failed+' · Отправлено: '+r.sent+'</p><p class="muted">'+esc(r.error||'')+'</p><button class="btn" data-action="close">Закрыть</button>');return;}if(action==='add-master'){state.admin.masters=collectMasterRows();state.admin.masters.push({id:'',name:'',specialty:'',active:true});renderEditor();}
 if(action==='install')await install();if(action==='close'||b.classList.contains('close'))close();
 if(action==='export-bookings'){const r=LOCAL_DEMO?{filename:'bookings.csv',content:'Дата;Услуга;Имя;Статус\r\n'+state.admin.bookings.map(x=>[x.date,x.service,x.name,x.status].map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(';')).join('\r\n')}:await api('/admin/export','GET',undefined,true);const url=URL.createObjectURL(new Blob(['\ufeff'+r.content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=r.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
