document.addEventListener('click',e=>{const button=e.target.closest('[data-action=photo-link]');if(!button)return;if(pendingActions){toast('Дождитесь загрузки фотографии.');return;}const input=button.closest('.photo-editor').querySelector('input[name]');input.type='text';input.required=input.name==='image';input.closest('label').hidden=false;input.focus();const form=input.form;form.dataset.dirty='1';form.dataset.editVersion=String(Number(form.dataset.editVersion||0)+1);});
let photoUploads=0;
document.addEventListener('change',async e=>{if(e.target.name==='date'&&e.target.closest('#reschedule-form')){e.target.form.elements.time.value='';fillRescheduleTimes();}
 const row=e.target.closest('.photo-editor');if(!row)return;
 const preview=row.querySelector('.photo-preview'),status=row.querySelector('.photo-status'),input=row.querySelector('input[name]');
 if(e.target===input){preview.src=asset(input.value);preview.hidden=!input.value;return;}
 if(!e.target.matches('[data-photo-upload]')||!e.target.files[0])return;if(photoUploads){e.target.value='';toast('Дождитесь загрузки фотографии.');return;}
 const file=e.target.files[0],form=input.form,saveButton=form.querySelector('button[type=submit],button:not([type])'),previous={value:input.value,type:input.type,required:input.required,hidden:input.closest('label').hidden};
 if(!['image/jpeg','image/png','image/webp'].includes(file.type)){status.textContent='Выберите JPEG, PNG или WebP';e.target.value='';return;}
 if(file.size>10*1024*1024){status.textContent='Фото должно быть не больше 10 МБ';e.target.value='';return;}
 const local=URL.createObjectURL(file);preview.src=local;preview.hidden=false;status.textContent='Загружаем фото…';photoUploads++;pendingActions++;saveButton.disabled=true;input.disabled=true;
 try{
  const result=await requestJson(BASE+'api/admin/uploads',{method:'POST',headers:{Authorization:'Bearer '+state.adminToken,'Content-Type':file.type},body:file},30000);input.value=result.url;input.type='hidden';input.required=false;input.closest('label').hidden=true;preview.src=asset(result.url);status.textContent=input.name==='heroImage'?'Фото загружено. Нажмите «Сохранить настройки».':'Фото загружено. Нажмите «Сохранить работы» для публикации.';
 }catch(error){input.value=previous.value;input.type=previous.type;input.required=previous.required;input.closest('label').hidden=previous.hidden;preview.src=asset(previous.value);preview.hidden=!previous.value;status.textContent=error.message;toast(error.message);}
 finally{URL.revokeObjectURL(local);e.target.value='';input.disabled=false;photoUploads--;pendingActions--;saveButton.disabled=photoUploads>0;flushRender();}
});
document.addEventListener('change',async e=>{if(e.target.name==='masterId'&&e.target.closest('#booking-form')){state.masterId=e.target.value;state.slot='';$('#booking-form [name=time]').value='';await loadSlots();}if(e.target.name==='date'&&e.target.closest('#booking-form')){state.date=e.target.value;state.slot='';$('#booking-form [name=time]').value='';await loadSlots();}if(e.target.name==='admin-day'){state.day=e.target.value;render();}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(submitting.has(f))return;submitting.add(f);pendingActions++;const editVersion=f.dataset.editVersion,b=Object.fromEntries(new FormData(f)),submit=f.querySelector('button[type=submit],button:not([type])');let succeeded=false;if(submit)submit.disabled=true;try{
 if(await telegramUi.submit(f,b)){succeeded=true;return;}
 if(f.id==='booking-form'){if(b.mode!=='master'&&!b.time)throw Error('Выберите свободное время');if(b.mode==='master'&&!b.masterId)throw Error('Выберите мастера');const r=await api('/bookings','POST',b);f.dataset.completed='1';state.draft={};if(r.guest){state.guest=r.guest;state.guestBooking=r.booking;state.page='guest';location.hash='guest='+r.guest.id+'.'+r.guest.token;render();window.scrollTo(0,0);await refreshAfterWrite();}else{state.clientToken||='cookie';clientStorage.setItem(CLIENT_KEY,state.clientToken);await go('account');}toast(r.booking.status==='confirmed'?'Запись подтверждена':'Заявка отправлена');}
 if(f.id==='email-login'||f.id==='phone-login'){const r=await api('/client/login','POST',b);state.clientToken=r.token||'cookie';clientStorage.setItem(CLIENT_KEY,state.clientToken);await refreshAfterWrite();if(state.guest&&(state.client?.customer.verified||state.client?.customer.emailVerified))modal('<h2>Добавить гостевую запись?</h2><p class="muted">Добавьте открытую по личной ссылке запись в историю вашего кабинета.</p><button class="btn" data-action="claim-guest">Добавить в историю</button>');}
 if(f.id==='register-form'){const r=await api('/auth/register','POST',{...b,guestId:state.guest?.id,guestToken:state.guest?.token});modal('<h2>Проверьте почту</h2><p class="muted">'+esc(r.message)+'</p>'+ (r.demoLink?'<p class="notice">Это демоверсия: письмо не отправляется. Откройте тестовую ссылку.</p><a class="btn" href="'+esc(r.demoLink)+'" data-action="demo-email-link">Открыть письмо демо</a>':'')+'<button class="quiet" data-action="close" style="margin-top:18px">Закрыть</button>');}
 if(f.id==='forgot-form'){const r=await api('/auth/forgot','POST',b);modal('<h2>Восстановление доступа</h2><p class="muted">'+esc(r.message)+'</p>'+(r.demoLink?'<a class="btn" href="'+esc(r.demoLink)+'" data-action="demo-email-link">Открыть письмо демо</a>':'')+'<button class="quiet" data-action="close" style="margin-top:18px">Закрыть</button>');}
 if(f.id==='verify-form'||f.id==='reset-form'){if(b.password!==b.confirmation)throw Error('Пароли не совпадают');const verified=f.id==='verify-form';const r=await api(verified?'/auth/verify':'/auth/reset','POST',{token:state.linkToken,password:b.password});state.linkToken='';if(verified){state.guest=null;state.guestBooking=null;state.clientToken=r.token||'cookie';clientStorage.setItem(CLIENT_KEY,state.clientToken);}else{state.clientToken='';state.client=null;clientStorage.removeItem(CLIENT_KEY);}state.authView='login';await go('account');toast(verified?'Почта подтверждена. Кабинет создан.':'Пароль изменен. Войдите в кабинет.');}
 if(f.id==='client-login'){const r=await api('/client/login','POST',b);state.clientToken=r.token;clientStorage.setItem(CLIENT_KEY,r.token);await refreshAfterWrite();}
 if(f.id==='admin-login'){const r=await api('/admin/login','POST',b,true);state.adminToken=r.token;adminStorage.setItem(ADMIN_KEY,r.token);await refreshAfterWrite();}
 if(f.id==='settings-form'){if(photoUploads)throw Error('Дождитесь загрузки фотографии');b.days=new FormData(f).getAll('days').map(Number);await api('/admin/settings','PUT',b,true);await refreshAfterWrite();toast('Расписание сохранено');}
 if(f.id==='masters-form'){await api('/admin/masters','PUT',{masters:collectMasterRows()},true);await refreshAfterWrite();toast('Мастера сохранены');}if(f.id==='services-form'){await api('/admin/services','PUT',{services:collectRows('.service-edit').map((x,i)=>({...x,id:state.admin.services[i]?.id}))},true);await refreshAfterWrite();toast('Услуги сохранены');}
 if(f.id==='promos-form'){await api('/admin/promos','PUT',{promos:collectRows('.promo-edit')},true);await refreshAfterWrite();toast('Промокоды сохранены');}
 if(f.id==='portfolio-form'){if(photoUploads)throw Error('Дождитесь загрузки фотографий');const missing=[...f.querySelectorAll('.portfolio-edit')].find(row=>!row.querySelector('[name=image]').value.trim());if(missing){missing.querySelector('.photo-status').textContent='Загрузите фотографию или укажите ссылку на неё';missing.querySelector('[data-photo-upload]').focus();throw Error('Для каждой работы добавьте фотографию или ссылку');}await api('/admin/portfolio','PUT',{portfolio:collectRows('.portfolio-edit')},true);await refreshAfterWrite();toast('Работы сохранены');}
 if(f.classList.contains('review-edit')){await api('/admin/reviews/'+f.dataset.id,'PATCH',{...b,featured:new FormData(f).has('featured')},true);await refreshAfterWrite();toast('Отзыв обновлен');}
 if(f.id==='reschedule-form'){await api('/admin/bookings/'+f.dataset.id,'PATCH',{...b,action:'reschedule'},true);close();await refreshAfterWrite();toast('Время записи изменено');}
 if(f.id==='edit-booking'){await api('/admin/bookings/'+f.dataset.id,'PATCH',b,true);close();await refreshAfterWrite();toast('Запись обновлена');}
 if(f.id==='admin-message'){await api('/admin/bookings/'+f.dataset.id,'PATCH',b,true);close();await refreshAfterWrite();toast('Сообщение отправлено');}
 if(f.id==='client-message'){await bookingAction(f.dataset.id,'PATCH',{...b,action:'message'});close();await refreshAfterWrite();toast('Сообщение отправлено');}
 if(f.id==='review-form'){await api('/reviews','POST',b);f.reset();toast('Спасибо! Отзыв отправлен на модерацию');}
 if(f.id==='password-form'){await api('/admin/password','POST',b,true);state.adminToken='';state.admin=null;adminStorage.removeItem(ADMIN_KEY);await refreshAfterWrite();toast('Пароль изменен. Войдите снова.');}
 succeeded=true;}catch(err){toast(err.message);}finally{if(succeeded&&f.dataset.editVersion===editVersion)delete f.dataset.dirty;submitting.delete(f);pendingActions--;if(submit)submit.disabled=false;flushRender(succeeded);}});
